    58  static unsigned long minimumnewlen = 30;
    59  /*
    60  struct dwarfstring_s {
    61     char *        s_data;
    62     unsigned long s_size;
    63     unsigned long s_avail;
    64     unsigned char s_malloc;
    65  };
    66  */
    67
    68  int
    69  dwarfstring_constructor(struct dwarfstring_s *g)
    70  {
    71      g->s_data = "";
    72      g->s_size = 0;
    73      g->s_avail = 0;
    74      g->s_malloc = FALSE;
    75      return TRUE;
    76  }
    77
    78  static int
    79  dwarfstring_resize_to(struct dwarfstring_s *g,unsigned long newlen)
    80  {
    81      char *b = 0;
    82      unsigned long lastpos =
    83          g->s_size - g->s_avail;
    84      unsigned long malloclen = newlen+1;
    85
    86      if (malloclen < minimumnewlen) {
    87          malloclen = minimumnewlen;
    88      }
    89      b = malloc(malloclen);
    90      if (!b) {
    91          return FALSE;
    92      }
    93      if (lastpos > 0) {
    94          memcpy(b,g->s_data,lastpos);
    95      }
    96      if (g->s_malloc) {
    97          free(g->s_data);
    98          g->s_data = 0;
    99      }
   100      g->s_data = b;
   101      g->s_data[lastpos] = 0;
   102      g->s_size = newlen;
   103      g->s_avail = newlen - lastpos;
   104      g->s_malloc = TRUE;
   105      return TRUE;
   106  }
