   725  _dwarf_debuglink_finder_internal(
   726      char         **gl_pathnames,
   727      unsigned int   gl_pathcount,
   728      char         * path_in,
   729      dwarfstring    *m,
   730      int * fd_out,
   731      int * errcode)
   732  {
   733      int res = 0;
   734      /*  This local dbg is opened and then dwarf_finish()
   735          here.  No dbg in the arguments! */
   736      Dwarf_Debug    dbg = 0;
   737      char         * path = 0;
   738      Dwarf_Error    error = 0;
   739      unsigned int   p = 0;
   740      char          *debuglinkpath = 0;
   741      unsigned char *crc = 0;
   742      char          *debuglinkfullpath = 0; /* must be freed*/
   743      unsigned       debuglinkfullpath_strlen = 0;
   744      unsigned       buildid_type = 0;
   745      char         * buildidownername = 0;
   746      unsigned char *buildid = 0;
   747      unsigned       buildid_length = 0;
   748      char        ** paths = 0; /* must be freed */
   749      unsigned       paths_count = 0;
   750      unsigned       i = 0;
   751
   752      path = path_in;
   753      /*  This path will work.
   754          Already know the file is there. */
   755      res = dwarf_init_path(path,
   756          0,0,
   757          DW_GROUPNUMBER_ANY,
   758          0,0, &dbg, &error);
   759      if (res == DW_DLV_ERROR) {
   760          *errcode = dwarf_errno(error);
   761          dwarf_dealloc_error(dbg,error);
   762          error = 0;
   763          return res;
   764      }
   765      if (res == DW_DLV_NO_ENTRY) {
   766          return res;
   767      }
   768      for (p = 0;  p < gl_pathcount; ++p) {
   769          const char *lpath = 0;
   770
   771          lpath = (const char *)gl_pathnames[p];
   772          res = dwarf_add_debuglink_global_path(dbg,
   773              lpath, &error);
   774          if (res != DW_DLV_OK){
   775              if (res == DW_DLV_ERROR) {
   776                  *errcode = dwarf_errno(error);
   777                  dwarf_dealloc_error(dbg,error);
   778                  error = 0;
   779              }
   780              dwarf_finish(dbg);
   781              return res;
   782          }
   783      }
   784      res = dwarf_gnu_debuglink(dbg,
   785          &debuglinkpath,
   786          &crc, &debuglinkfullpath, &debuglinkfullpath_strlen,
   787          &buildid_type, &buildidownername,
   788          &buildid, &buildid_length,
   789          &paths, &paths_count, &error);
   790      if (res == DW_DLV_ERROR) {
   791          *errcode = dwarf_errno(error);
   792          dwarf_dealloc_error(dbg,error);
   793          dwarf_finish(dbg);
   794          return DW_DLV_NO_ENTRY;
   795      }
   796      if (res == DW_DLV_NO_ENTRY) {
   797          /*  There is no debuglink section */
   798          dwarf_finish(dbg);
   799          return DW_DLV_NO_ENTRY;
   800      }
   801      for (i =0; i < paths_count; ++i) {
   802          char *pa =     paths[i];
   803          int pfd = 0;
   804
   805          /*  First, open the file to determine if it exists.
   806              If not, loop again */
   807
   808          pfd = open(pa,O_RDONLY|O_BINARY);
   809          if (pfd  < 0) {
   810              /*  This is the usual path. */
   811              continue;
   812          }
   813          close(pfd);
   814          /* ASSERT: never returns DW_DLV_ERROR */
   815          res = _dwarf_debuglink_finder_newpath(
   816              pa,crc,buildid_length, buildid,
   817              m,fd_out);
   818          if (res == DW_DLV_OK) {
   819              free(debuglinkfullpath);
   820              free(paths);
   821              paths = 0;
   822              dwarf_finish(dbg);
   823              return DW_DLV_OK;
   824          }
   825          *errcode = 0;
   826          continue;
   827      }
   828      free(debuglinkfullpath);
   829      free(paths);
   830      paths = 0;
   831      dwarf_finish(dbg);
   832      return DW_DLV_NO_ENTRY;
   833  }
